CREATE DATABASE IF NOT EXISTS tunning CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tunning;

CREATE TABLE IF NOT EXISTS dados_csv (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    arquivo_origem VARCHAR(255) NOT NULL,
    periodo VARCHAR(100) NOT NULL,
    dados JSON NOT NULL,
    observacoes TEXT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_dados_csv_origem_periodo (arquivo_origem, periodo),
    KEY idx_dados_csv_periodo (periodo)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


select * from dados_csv;